function validate([nums, diff]) {
  if (!Array.isArray(nums) || nums.length < 3 || nums.length > 200) return 'nums needs 3 to 200 values.';
  for (let i = 0; i < nums.length; i++) {
    if (!Number.isInteger(nums[i]) || nums[i] < 0 || nums[i] > 200) return 'Each value is an integer from 0 to 200.';
    if (i > 0 && nums[i] <= nums[i - 1]) return 'nums must be strictly increasing.';
  }
  if (!Number.isInteger(diff) || diff < 1 || diff > 50) return 'diff is an integer from 1 to 50.';
  return null;
}

