function generate(rand, size) {
  const large = size === 'large';
  const want = large ? 60 + Math.floor(rand() * 141) : 3 + Math.floor(rand() * 8);
  const top = large ? 200 : want - 1 + Math.floor(rand() * 12);
  const pool = Array.from({ length: top + 1 }, (_, v) => v);
  for (let i = pool.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [pool[i], pool[j]] = [pool[j], pool[i]];
  }
  const nums = pool.slice(0, want).sort((a, b) => a - b);
  const diff = 1 + Math.floor(rand() * (large ? 50 : 4));
  return [nums, diff];
}
